var n=`0806-muriwo-unedovi`;var t=`world-0806`;var a=`ZW`;var s=`eastern-africa`;var o=4;var r=27;var l={en:`Muriwo Unedovi`,ua:`Зелень з арахісовим маслом`};var d={en:`Muriwo Unedovi is a Zimbabwe dish made with yellow onion, garlic, collard greens, tomato. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Зелень з арахісовим маслом, страва кухні країни Зімбабве. Основні складники: жовта цибуля, часник, листова капуста колард, помідор. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var g=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 7 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 7 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:7,i:[[`yellow-onion`,120,`g`],[`canola-oil`,25,`ml`],[`garlic`,3,`clove`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 12 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 12 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:12,i:[[`collard-greens`,470,`g`],[`tomato`,200,`g`],[`water`,150,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`peanut-butter`,110,`g`],[`water`,140,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`crushed-red-pepper`,2,`g`]]}];var m={slug:n,id:t,country:`ZW`,region:s,servings:4,minutes:27,title:l,text:d,steps:g};export{a as country,m as default,t as id,r as minutes,s as region,o as servings,n as slug,g as steps,d as text,l as title};